const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: 'v' },
      { kind: 'text', payload: 'g' },
      { kind: 'text', payload: '静止释放' }
    ];
  },
  render: function (input, metrics) {
    var w = input.viewport.widthDu;
    var h = input.viewport.heightDu;
    var ball = visualSdk.circle(150, 110, 24);
    var vShaft = visualSdk.polyline([[150, 142], [150, 255]]);
    var vHead = [['M', 150, 272], ['L', 138, 250], ['L', 162, 250], ['Z']];
    var gShaft = visualSdk.polyline([[245, 80], [245, 188]]);
    var gHead = [['M', 245, 205], ['L', 233, 183], ['L', 257, 183], ['Z']];
    return {
      schemaVersion: 1,
      sceneId: 'free-fall',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: w, height: h },
      paths: [
        { id: 'ball', commands: ball },
        { id: 'vShaft', commands: vShaft },
        { id: 'vHead', commands: vHead },
        { id: 'gShaft', commands: gShaft },
        { id: 'gHead', commands: gHead }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'ball', fill: '#e6a23c' },
          { type: 'path', pathId: 'vShaft', fill: '#26354a', stroke: { width: 3, cap: 'round' } },
          { type: 'path', pathId: 'vHead', fill: '#26354a' },
          { type: 'path', pathId: 'gShaft', fill: '#26354a', stroke: { width: 3, cap: 'round' } },
          { type: 'path', pathId: 'gHead', fill: '#26354a' },
          { type: 'label', contentId: metrics[0].contentId, anchor: { x: 162, y: 205 }, hAlign: 'left', vAlign: 'middle', color: '#26354a' },
          { type: 'label', contentId: metrics[1].contentId, anchor: { x: 257, y: 140 }, hAlign: 'left', vAlign: 'middle', color: '#26354a' },
          { type: 'label', contentId: metrics[2].contentId, anchor: { x: 150, y: 78 }, hAlign: 'center', vAlign: 'bottom', color: '#26354a' }
        ]
      }
    };
  }
};
